create or replace function public.reserve_client_submission(p_application uuid,p_summary text,p_authorisation text,p_recipient text) returns jsonb language plpgsql security definer set search_path='' as $$ declare a public.applications%rowtype;j public.jobs%rowtype;cl public.clients%rowtype;c public.candidates%rowtype;s public.candidate_submissions%rowtype;delivery uuid;co public.companies%rowtype; begin if not public.is_manager() or auth.uid() is null then raise exception 'Staff access required';end if; select * into a from public.applications where id=p_application and company_id=public.current_company_id() for update;if not found then raise exception 'Application unavailable';end if; select * into s from public.candidate_submissions where application_id=a.id;if found then return jsonb_build_object('existing',true,'submission_id',s.id,'status',s.status);end if; if a.status<>'qualified' then raise exception 'Record a human qualification decision before submission';end if; if length(trim(coalesce(p_summary,'')))<10 or length(p_summary)>8000 or length(trim(coalesce(p_authorisation,'')))<10 then raise exception 'Reviewed summary and candidate permission required';end if; if exists(select 1 from public.screening_reports where application_id=a.id and reviewed_at is null) then raise exception 'Review screening evidence before sharing';end if; select * into j from public.jobs where id=a.job_id and company_id=a.company_id; if j.application_mode='register_interest' or j.status::text<>'published' then raise exception 'Candidate introductions require a current authorised client vacancy';end if; select * into cl from public.clients where id=j.client_id and company_id=a.company_id and status='active'; if not found or cl.email is null or lower(trim(p_recipient))<>lower(trim(cl.email)) then raise exception 'Confirm the active client contact recorded for this opportunity';end if; if cl.terms_accepted_at is null or cl.terms_version is null or cl.recruitment_fee_percent is null or cl.payment_terms_days is null then raise exception 'Client terms of business must be agreed before candidate introduction';end if; select * into co from public.companies where id=a.company_id; if co.legal_name is null or co.legal_address is null or co.privacy_email is null then raise exception 'Agency legal identity must be configured';end if; if j.genuine_vacancy_confirmed_at is null or j.start_date is null or coalesce(trim(j.duration_text),'')='' or coalesce(trim(j.duties),'')='' or coalesce(trim(j.work_days_hours),'')='' or coalesce(trim(j.health_safety_risks),'')='' or coalesce(trim(j.required_qualifications),'')='' or coalesce(trim(j.expenses_text),'')='' or coalesce(trim(j.minimum_remuneration_text),'')='' or coalesce(trim(j.pay_interval),'')='' or coalesce(trim(j.notice_period),'')='' then raise exception 'Vacancy compliance particulars are incomplete';end if; select * into c from public.candidates where id=a.candidate_id and company_id=a.company_id and erased_at is null;if not found then raise exception 'Candidate unavailable';end if; if coalesce(a.work_seeker_terms_agreed_at,c.work_seeker_terms_agreed_at) is null then raise exception 'Work-seeker terms must be agreed before work-finding services or introduction';end if; insert into public.outbound_deliveries(company_id,kind,idempotency_key,recipient,provider,status) values(a.company_id,'client_submission','submission:'||a.id,cl.email,'resend','reserved') returning id into delivery; insert into public.candidate_submissions(company_id,client_id,job_id,candidate_id,application_id,submitted_by,headline,recruiter_summary,status,recipient_email,reviewed_by,review_confirmed_at,delivery_id,candidate_authorisation) values(a.company_id,cl.id,j.id,c.id,a.id,auth.uid(),c.full_name||' — '||j.title,p_summary,'approved_to_send',cl.email,auth.uid(),now(),delivery,p_authorisation) returning * into s; return jsonb_build_object('existing',false,'submission_id',s.id,'delivery_id',delivery,'company_id',a.company_id,'recipient',cl.email,'subject','Candidate submission: '||j.title,'body',c.full_name||E'\nRole: '||j.title||E'\n\n'||p_summary); end $$; revoke all on function public.reserve_client_submission(uuid,text,text,text) from public,anon; grant execute on function public.reserve_client_submission(uuid,text,text,text) to authenticated,service_role;
